<?php
function instructor_actions(string $action,int $cid,array $stamp):never{global $config;switch($action){
 case 'course_save':
  $u=requireUser('instructor');$title=textInput('title',5,150);$description=textInput('description',20,2000);$category=(int)($_POST['category_id']??0);$cover=coverKey();if(!one('SELECT id FROM categories WHERE id=?',[$category]))reject('Danh mục không hợp lệ.');
  if($cid){transaction(function()use($cid,$title,$description,$category,$cover){ownerCourse($cid);lockCourse($cid);run('UPDATE courses SET title=?,description=?,category_id=?,cover_key=?,updated_at=? WHERE id=?',[$title,$description,$category,$cover,now(),$cid]);});}else{$cid=insertRow('courses',['instructor_id'=>$u['id'],'category_id'=>$category,'title'=>$title,'description'=>$description,'cover_key'=>$cover,'status'=>'draft']+$stamp);}flash('Đã lưu thông tin khóa học.');go('edit',['id'=>$cid]);
 case 'course_state':
  $u=requireUser();mustConfirm();$target=(string)($_POST['target']??'');transaction(function()use($u,$cid,$target){if($u['role']==='instructor')ownerCourse($cid);elseif($u['role']!=='admin'||$target!=='archived')reject('Không có quyền đổi trạng thái.',403);$c=lockCourse($cid);if($target==='published'){if(!in_array($c['status'],['draft','archived'],true))reject('Chuyển trạng thái không hợp lệ.',409);$chs=all('SELECT id FROM chapters WHERE course_id=?',[$cid]);if(!$chs)reject('Khóa cần ít nhất một chương.');foreach($chs as $ch)if(!(int)val('SELECT COUNT(*) FROM lessons WHERE chapter_id=?',[$ch['id']]))reject('Mỗi chương cần ít nhất một bài.');if(count(questionsFor($cid))<5)reject('Cần quiz hợp lệ với ít nhất 5 câu.');}
   elseif($target==='draft'){if($c['status']!=='published'||hasEnrollment($cid))reject('Chỉ đưa published chưa enrollment về nháp.',409);}
   elseif($target==='archived'){if($c['status']==='draft')reject('Không lưu trữ khóa nháp.',409);}
   else reject('Trạng thái không hợp lệ.');run('UPDATE courses SET status=?,updated_at=? WHERE id=?',[$target,now(),$cid]);});flash('Đã cập nhật trạng thái.');go($u['role']==='admin'?'admin':'edit',$u['role']==='admin'?['tab'=>'courses']:['id'=>$cid]);
 case 'course_delete':
  ownerCourse($cid);mustConfirm();transaction(function()use($cid){$c=lockCourse($cid);structureOpen($c);run('DELETE FROM courses WHERE id=?',[$cid]);});flash('Đã xóa bản nháp.');go('instructor');
 case 'chapter_save':
  $title=textInput('title',2,150);$position=(int)($_POST['position']??1);if($position<1)reject('Thứ tự phải lớn hơn 0.');$chapterId=(int)($_POST['chapter_id']??0);ownerCourse($cid);transaction(function()use($cid,$chapterId,$title,$position,$stamp){$c=lockCourse($cid);if($chapterId){$ch=one('SELECT * FROM chapters WHERE id=? AND course_id=?',[$chapterId,$cid]);if(!$ch)reject('Không tìm thấy chương.',404);if($position!==(int)$ch['position'])structureOpen($c);run('UPDATE chapters SET title=?,position=?,updated_at=? WHERE id=?',[$title,$position,now(),$chapterId]);}else{structureOpen($c);insertRow('chapters',['course_id'=>$cid,'title'=>$title,'position'=>$position]+$stamp);}});flash('Đã lưu chương.');go('edit',['id'=>$cid,'tab'=>'content']);
 case 'chapter_delete':
  ownerCourse($cid);mustConfirm();transaction(function()use($cid){structureOpen(lockCourse($cid));run('DELETE FROM chapters WHERE id=? AND course_id=?',[(int)($_POST['chapter_id']??0),$cid]);});flash('Đã xóa chương và các bài nháp.');go('edit',['id'=>$cid,'tab'=>'content']);
 case 'lesson_save':
  ownerCourse($cid);$title=textInput('title',2,150);$body=textInput('body',50,12000);$video=trim((string)($_POST['youtube_video_id']??''));if($video!==''&&!preg_match('/^[A-Za-z0-9_-]{11}$/',$video))reject('YouTube ID cần đúng 11 ký tự.');$position=(int)($_POST['position']??1);if($position<1)reject('Thứ tự phải lớn hơn 0.');$lid=(int)($_POST['lesson_id']??0);$chapter=(int)($_POST['chapter_id']??0);
  transaction(function()use($cid,$title,$body,$video,$position,$lid,$chapter,$stamp){$c=lockCourse($cid);if($lid){$l=lessonCourse($lid);if((int)$l['course_id']!==$cid)reject('Không tìm thấy bài.',404);if((int)$l['position']!==$position)structureOpen($c);run('UPDATE lessons SET title=?,body=?,youtube_video_id=?,position=?,updated_at=? WHERE id=?',[$title,$body,$video?:null,$position,now(),$lid]);}else{structureOpen($c);if(!one('SELECT id FROM chapters WHERE id=? AND course_id=?',[$chapter,$cid]))reject('Chương không thuộc khóa.');insertRow('lessons',['chapter_id'=>$chapter,'title'=>$title,'body'=>$body,'youtube_video_id'=>$video?:null,'position'=>$position]+$stamp);}});flash('Đã lưu bài học.');go('edit',['id'=>$cid,'tab'=>'content']);
 case 'lesson_delete':
  ownerCourse($cid);mustConfirm();transaction(function()use($cid){structureOpen(lockCourse($cid));$lid=(int)($_POST['lesson_id']??0);if((int)lessonCourse($lid)['course_id']!==$cid)reject('Không tìm thấy bài.',404);run('DELETE FROM lessons WHERE id=?',[$lid]);});flash('Đã xóa bài nháp.');go('edit',['id'=>$cid,'tab'=>'content']);
 case 'quiz_save':
  ownerCourse($cid);$qs=$_POST['questions']??[];if(!is_array($qs)||count($qs)<5||count($qs)>20)reject('Quiz cần 5–20 câu.');$clean=[];foreach($qs as $q){$prompt=trim((string)($q['prompt']??''));$explanation=trim((string)($q['explanation']??''));$answers=$q['answers']??[];if(is_array($answers))$answers=array_values($answers);$correct=(int)($q['correct']??-1);if(length($prompt)<5||length($prompt)>500||length($explanation)>1000||!is_array($answers)||count($answers)!==4||$correct<0||$correct>3)reject('Mỗi câu cần prompt hợp lệ, bốn lựa chọn và một đáp án đúng.');foreach($answers as &$a){$a=trim((string)$a);if(length($a)<1||length($a)>250)reject('Mỗi lựa chọn cần 1–250 ký tự.');}$clean[]=['prompt'=>$prompt,'explanation'=>$explanation,'answers'=>$answers,'correct'=>$correct];unset($a);}
  transaction(function()use($cid,$clean,$stamp){structureOpen(lockCourse($cid));$quiz=one('SELECT * FROM quizzes WHERE course_id=?',[$cid]);$qid=$quiz?(int)$quiz['id']:insertRow('quizzes',['course_id'=>$cid]+$stamp);run('DELETE FROM questions WHERE quiz_id=?',[$qid]);foreach($clean as $i=>$q){$id=insertRow('questions',['quiz_id'=>$qid,'prompt'=>$q['prompt'],'explanation'=>$q['explanation'],'position'=>$i+1]+$stamp);foreach($q['answers'] as $j=>$text)insertRow('answers',['question_id'=>$id,'text'=>$text,'is_correct'=>(int)($q['correct']===$j),'position'=>$j+1]+$stamp);}});flash('Đã lưu toàn bộ quiz.');go('edit',['id'=>$cid,'tab'=>'quiz']);
default:reject('Thao tác không tồn tại.',404);}}
